// === Tab: mySketch ===
let hive = [];

const hs3 = Math.sqrt(3)/2; //half sqrt 3
const s3 = Math.sqrt(3);

let h_amt = 9; let v_amt = 9; //v_amt can only be odd, (idk what happens if its even it probably still works)

let size = 60;

let pal = ["#0c2046", "#f67e7d", "#fffaf2"];
function setup() {
	shuffle(pal, true);

	createCanvas(600, 600);
	// noLoop() removed for animation
	noFill();
	stroke(pal[1]);
	strokeWeight(10);
	strokeCap(ROUND);

	for(let x=0; x<h_amt; x++){
		let col = [];
		for(let y=0; y<v_amt; y++){
			if(x-y>=h_amt-floor(v_amt/2) || x-y<=-ceil(v_amt/2)) col.push(false);
			else col.push({x:x, y:y});
		}
		hive.push(col);
	}
}

function draw() {
	background(pal[0]);

	translate(size*ceil(v_amt/2)/2, size*hs3/2);
	translate(width/2-size*h_amt/2, height/2-(v_amt/2)*size*hs3);

	for(let x of hive){
		for(let i of x){
			if(i){
				hexagon(i.x*size-i.y*size*0.5, i.y*size*hs3, size/2);
			}
		}
	}
}

function hexagon(w, h, s){
	push();
	translate(w, h);
	rotate(TAU*floor(random(1, 7))/6);
	arc(0, -cos(PI/6)*s-s/(2*s3), 2*s/s3, 2*s/s3, PI/6, PI*5/6);
	arc(0, cos(PI/6)*s+s/(2*s3), 2*s/s3, 2*s/s3, PI*7/6, PI*11/6);
	line(-s, 0, s, 0);
	pop();
}
